(()=>{'use strict';
const preference=matchMedia('(prefers-reduced-motion: reduce)');const active=new Set();
function run(element,keyframes,options){if(preference.matches||!element.animate)return null;const animation=element.animate(keyframes,options);active.add(animation);animation.finished.then(()=>active.delete(animation),()=>active.delete(animation));return animation;}
const rise=[{opacity:0,transform:'translateY(24px)'},{opacity:1,transform:'translateY(0)'}];
const timing={duration:650,easing:'cubic-bezier(.22,.8,.24,1)',fill:'backwards'};
const hero=document.querySelector('.hero-copy,.page-hero .shell,.not-found');
if(hero){[...hero.children].filter(el=>!el.classList.contains('breadcrumbs')).forEach((el,i)=>run(el,rise,{...timing,duration:750,delay:70+i*65}));}
const revealTargets=[...document.querySelectorAll('.section-heading,.catalog-notice,.product-card,.documentation-grid>div,.info-card,.split-section>div,.statement-panel,.channel-card,.ordering-steps li,.faq-item,.compound-panel,.detail-content,.detail-support>div,.related-section,.callout-inner,.footer-main>div,.discovery-grid>div')];
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;observer.unobserve(entry.target);const siblings=[...entry.target.parentElement.children],index=Math.max(0,siblings.indexOf(entry.target));run(entry.target,rise,{...timing,delay:Math.min(index,3)*65});}},{threshold:.08,rootMargin:'0px 0px -24px 0px'});revealTargets.forEach(el=>observer.observe(el));}
document.querySelectorAll('.faq-item').forEach(item=>{const summary=item.querySelector('summary');let animation=null,targetOpen=item.open,revision=0;summary.addEventListener('click',event=>{if(preference.matches||!item.animate){targetOpen=!item.open;return;}event.preventDefault();const start=item.offsetHeight,token=++revision;targetOpen=!targetOpen;animation?.cancel();item.style.height='';item.open=true;const end=targetOpen?item.offsetHeight:summary.offsetHeight;item.style.height=start+'px';animation=run(item,[{height:start+'px'},{height:end+'px'}],{duration:320,easing:'cubic-bezier(.22,.8,.24,1)'});const finish=()=>{if(token!==revision)return;item.open=targetOpen;item.style.height='';animation=null;};if(animation){animation.onfinish=finish;animation.oncancel=finish;}else finish();});});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-product]:not([hidden])').forEach((card,i)=>run(card,[{opacity:.35,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{...timing,duration:400,delay:i*40}));}));
if(matchMedia('(hover:hover) and (pointer:fine)').matches)document.querySelectorAll('.product-card').forEach(card=>{card.addEventListener('pointermove',event=>{if(preference.matches)return;const r=card.getBoundingClientRect();card.style.setProperty('--tilt-x',((.5-(event.clientY-r.top)/r.height)*4).toFixed(2)+'deg');card.style.setProperty('--tilt-y',(((event.clientX-r.left)/r.width-.5)*4).toFixed(2)+'deg');});card.addEventListener('pointerleave',()=>{card.style.removeProperty('--tilt-x');card.style.removeProperty('--tilt-y');});});
preference.addEventListener('change',event=>{if(event.matches){for(const animation of active)animation.cancel();active.clear();}});
})();
